// fundamental
import React from 'react';
import { Component } from 'react'
import { connect } from 'react-redux'
// Actions
import { welcome } from '../actions/app'
// 
import {
  Grid,
  Tabs,
  Tab,
} from '@material-ui/core'  
// components
import Header from './header'
import Footer from './footer'

interface AppProps {
  welcome?(): any,
  title?: string,
}

interface State {
  currentTab?: string
}

class App extends Component<AppProps, State>{
  constructor(props: AppProps) {
    super(props)
    this.state = {
      currentTab:'doc',
    }
  }
  componentDidMount() {
    this.props.welcome!()
  }
  changeTab(e:any, v:any) {
    this.setState({
      currentTab: v
    })
  }
  render() {
    return (
      <React.Fragment>
      <div className="App">
        <Header title={this.props.title} />
        <Footer />
      </div>
      </React.Fragment>
    );
  }
}

export default connect(
  (state:any)=>state.app,
  {
    welcome,
  },
)(App);
